export const ThemedCardActionArea = {
    styleOverrides: {
        root: ({ theme }) => ({
            "&:hover": {
                backgroundColor: theme.palette.action.hover,
            },
            // need specific styles order, otherwise active is not applied because it gets overidden by hover
            // eslint-disable-next-line sort-keys/sort-keys-fix
            "&:active": {
                backgroundColor: theme.palette.action.selected,
            },
        }),
    },
};
